// #a8e7e24c31c0c182cdc6043e — ссылка «לכל הדוחות המוכנים» в панели «ממתינים להחלטה שלכם» открывает
// тот же набор, что показывает панель (готовые отчёты без החלטת גיוס). Кейс DASH-001.
// Только чтение — @prod-safe. Имена карточек панели читаются в рантайме (данные меняются).
import * as path from 'path';
import { test, expect } from '@playwright/test';
import { candidateRows, decisionCell, statusFilter, rowsByName } from './support';

test.use({ storageState: path.resolve(__dirname, '../../../auth/business.json') });

test.describe('Дашборд — ссылка «לכל הדוחות המוכנים» (#a8e7e24c31c0c182cdc6043e)', () => {
  test('ссылка «לכל הדוחות המוכנים» открывает тот же набор, что панель @desktop @prod-safe #a8e7e24c31c0c182cdc6043e', async ({ page }) => {
    test.setTimeout(120_000);
    await page.goto('/');
    await expect(page.getByRole('heading', { name: 'ממתינים להחלטה שלכם' })).toBeVisible();
    await expect(page.getByText('דוחות מוכנים שעוד לא נקבע להם סטטוס גיוס · הוותיקים קודם')).toBeVisible();

    // Имена карточек панели — из подписи ссылки «לדוח של <имя>» каждой карточки.
    const cards = page.getByTestId('decision-row');
    await expect(cards.first(), 'в панели нет карточек — нечего сверять (нет готовых отчётов без решения?)').toBeVisible();
    const labels = await cards.getByRole('link', { name: /^לדוח של / }).evaluateAll((els) => els.map((e) => e.getAttribute('aria-label') ?? ''));
    const names = labels.map((l) => l.replace(/^לדוח של /, '').trim()).filter(Boolean);
    expect(names.length, 'имена карточек панели').toBe(await cards.count());
    test.info().annotations.push({ type: 'panel', description: names.join(' · ') });

    // Источник: AC — «פותח את אותה קבוצה שהפאנל מציג (דוחות מוכנים שעדיין אין להם החלטת גיוס)».
    const link = page.getByRole('link', { name: 'לכל הדוחות המוכנים' });
    await expect(link).toHaveAttribute('href', '/candidates?status=awaiting_decision');
    await link.click();
    await page.waitForURL(/\/candidates\?.*status=awaiting_decision/);
    await expect(statusFilter(page)).toHaveValue('awaiting_decision');
    await expect(statusFilter(page).locator('option:checked')).toHaveText('ממתינים להחלטה');

    // В каждой строке набора ссылки «החלטת גיוס» = «טרם נקבע».
    await expect(candidateRows(page).first()).toBeVisible();
    const cells = decisionCell(page);
    const n = await cells.count();
    expect(n).toBeGreaterThan(0);
    for (let i = 0; i < n; i++) await expect(cells.nth(i)).toHaveText('טרם נקבע');

    // Каждое имя из панели находится в наборе ссылки.
    for (const name of names) {
      await page.goto(`/candidates?status=awaiting_decision&q=${encodeURIComponent(name)}`);
      await expect(rowsByName(page, name).first(), `«${name}» из панели нет в наборе ссылки`).toBeVisible();
      await expect(decisionCell(page, rowsByName(page, name)).first()).toHaveText('טרם נקבע');
    }
  });
});
